import{groundHeight}from'./world.js?v=balance-8';
const B=globalThis.BABYLON;
export class VoxelEffects{
 constructor(scene){this.scene=scene;this.items=[];this.cursor=0;this.timer=0;this.materials={};for(const[c,color,emission,alpha]of[['smoke','#c3c5b8',0,.38],['hot','#fff1ba',1,1],['fire','#f99447',1,.9],['blue','#8edfff',1,.9],['dust','#baad84',0,.5],['spark','#ffd58a',2,1]]){const m=new B.StandardMaterial('particle '+c,scene);m.diffuseColor=B.Color3.FromHexString(color);m.emissiveColor=m.diffuseColor.scale(emission);m.specularColor=B.Color3.Black();m.alpha=alpha;this.materials[c]=m;}
 const geometry=B.MeshBuilder.CreateBox('voxel particle source',{size:1},scene);geometry.setEnabled(false);for(let i=0;i<420;i++){const m=geometry.clone('voxel particle '+i);m.isPickable=false;m.setEnabled(false);this.items.push({mesh:m,life:0,max:0,velocity:new B.Vector3(),size:1,type:'smoke'});}this.source=geometry;this.clouds=[];this.smokeCursor=0;this.impactCursor=0;this.flashLife=0;this.flash=new B.PointLight('impact flash',B.Vector3.Zero(),scene);this.flash.diffuse=B.Color3.FromHexString('#ffb268');this.flash.range=90;this.flash.intensity=0;
 const data=new Uint8Array(64*64*4);for(let y=0;y<64;y++)for(let x=0;x<64;x++){const u=(x-31.5)/31.5,v=(y-31.5)/31.5,r=Math.hypot(u,v),noise=.78+.10*Math.sin(x*.61+y*.27)+.08*Math.sin(x*.27-y*.49),i=(y*64+x)*4;data[i]=data[i+1]=data[i+2]=255;data[i+3]=Math.round(Math.max(0,1-r)**1.5*noise*255);}this.cloudTexture=B.RawTexture.CreateRGBATexture(data,64,64,scene,false,false,B.Texture.BILINEAR_SAMPLINGMODE);
 this.fireCloud=this.makeCloud('fuel fireball',650,'fire');this.blastSmoke=this.makeCloud('rolling explosion smoke',1500,'smoke');this.blastDust=this.makeCloud('ground dust front',1200,'dust');this.waterCloud=this.makeCloud('impact spray',1000,'water');this.wreckClouds=Array.from({length:6},(_,i)=>this.makeCloud('wreck smoke '+i,180,'trail'));this.contactClouds=Array.from({length:3},(_,i)=>this.makeCloud('scrape dust '+i,150,'dust'));
 }
 makeCloud(name,capacity,type){const ps=new B.ParticleSystem(name,capacity,this.scene);ps.particleTexture=this.cloudTexture;ps.emitter=B.Vector3.Zero();ps.emitRate=0;ps.updateSpeed=1/60;ps.minEmitPower=ps.maxEmitPower=1;ps.minAngularSpeed=-.7;ps.maxAngularSpeed=.7;ps.minInitialRotation=0;ps.maxInitialRotation=Math.PI*2;ps.blendMode=type==='fire'?B.ParticleSystem.BLENDMODE_ADD:B.ParticleSystem.BLENDMODE_STANDARD;ps.minLifeTime=type==='fire'?.25:type==='water'?.7:2;ps.maxLifeTime=type==='fire'?1.2:type==='water'?2.3:type==='trail'?3.2:6;ps.gravity=new B.Vector3(0,type==='water'?-9.81:type==='smoke'||type==='trail'?1.3:0,0);ps.direction1=new B.Vector3(-6,2,-6);ps.direction2=new B.Vector3(6,8,6);ps.minEmitBox=new B.Vector3(-2,-.1,-2);ps.maxEmitBox=new B.Vector3(2,2,2);ps.minSize=.8;ps.maxSize=3;const C=(r,g,b,a)=>new B.Color4(r,g,b,a);
 if(type==='fire'){ps.addColorGradient(0,C(1,.93,.62,.9));ps.addColorGradient(.28,C(1,.37,.055,.85));ps.addColorGradient(.7,C(.48,.075,.012,.5));ps.addColorGradient(1,C(.14,.03,.005,0));ps.addSizeGradient(0,1,2);ps.addSizeGradient(.35,4,7);ps.addSizeGradient(1,7,11);}
 else{const water=type==='water',dust=type==='dust';ps.addColorGradient(0,water?C(.74,.91,.96,.55):dust?C(.42,.32,.2,.50):C(.12,.115,.105,.60));ps.addColorGradient(.3,water?C(.79,.92,.94,.36):dust?C(.54,.45,.32,.36):C(.22,.215,.20,.53));ps.addColorGradient(1,water?C(.8,.93,.98,0):dust?C(.62,.54,.40,0):C(.4,.395,.38,0));const scale=type==='trail'?.35:water?.23:1;ps.addSizeGradient(0,.8*scale,2*scale);ps.addSizeGradient(.35,3.5*scale,6*scale);ps.addSizeGradient(1,8*scale,13*scale);ps.addDragGradient(0,0);ps.addDragGradient(1,.72);}
 ps.start();this.clouds.push(ps);return ps;
 }
 puff(ps,position,count,spread=2,speed=9){ps.emitter.copyFrom(position);ps.minEmitBox.set(-spread,0,-spread);ps.maxEmitBox.set(spread,spread*.6,spread);ps.direction1.set(-speed,speed*.15,-speed);ps.direction2.set(speed,speed*.75,speed);ps.manualEmitCount=Math.max(0,ps.manualEmitCount)+count;}
 explosion(position,{fuel=100,energy=90,ground=false,water=false}={}){const strength=Math.min(1.8,.65+energy/300),burn=.15+Math.min(1,fuel/75);this.flash.position.copyFrom(position);this.flashLife=.55;this.flash.intensity=18*burn;this.puff(this.fireCloud,position,Math.round(170*burn),3*strength,14*strength);this.puff(this.blastSmoke,position,Math.round(230*burn+110),3*strength,9*strength);if(ground)this.puff(water?this.waterCloud:this.blastDust,position,water?360:310,4,23*strength);for(let i=0;i<100;i++){const a=Math.random()*Math.PI*2,r=10+Math.random()*32;this.emit(position,new B.Vector3(Math.cos(a)*r,Math.random()*28,Math.sin(a)*r),'spark',.065+Math.random()*.14,.4+Math.random()*1.5);}}
 impactBurst(position,velocity,{water=false,metal=true,energy=40,small=false}={}){const ps=water?this.waterCloud:this.contactClouds[this.impactCursor++%this.contactClouds.length];this.puff(ps,position,small?8:35,.7,Math.min(22,energy*.18+4));if(metal&&!water)for(let i=0;i<(small?5:14);i++)this.emit(position,velocity.scale(.2).add(new B.Vector3((Math.random()-.5)*10,Math.random()*6,(Math.random()-.5)*10)),'spark',.055+Math.random()*.09,.3+Math.random()*.65);}
 wreckSmoke(position,velocity,time,fuel){const ps=this.wreckClouds[this.smokeCursor++%this.wreckClouds.length];this.puff(ps,position,3,.5,1.8);if(fuel>0&&time<2&&Math.random()<.5)this.emit(position,velocity.scale(.15).add(new B.Vector3(0,2,0)),'fire',.4+Math.random()*.5,.35);}

 emit(pos,velocity,type,size,life){const a=this.items[this.cursor++%this.items.length];a.mesh.position.copyFrom(pos);a.velocity.copyFrom(velocity);a.type=type;a.max=life;a.life=life;a.size=size;a.mesh.material=this.materials[type];a.mesh.scaling.setAll(size);a.mesh.rotation.set(Math.random(),Math.random(),Math.random());a.mesh.setEnabled(true);}
 exhaust(plane,state,dt){if(state.throttle<.01){this.timer=0;return;}this.timer+=dt;const q=plane.root.rotationQuaternion,m=B.Matrix.FromQuaternionToRef(q,new B.Matrix());const trans=p=>B.Vector3.TransformCoordinates(new B.Vector3(...p),plane.root.computeWorldMatrix(true));const back=B.Vector3.TransformNormal(new B.Vector3(0,0,-1),m);const inherited=state.velocity?state.velocity.scale(.85):new B.Vector3();const rate=plane.type==='jet'||plane.type==='ufo'?.019:.055;while(this.timer>rate){this.timer-=rate;if(state.reverse){for(const side of[-1,1]){const at=plane.moduleEmitters?.length?plane.moduleEmitters[side<0?0:1]:plane.type==='jet'?[side*1.3,-.1,-4.9]:[side*.74,-.42,2.55];const p=trans(at);const sideways=B.Vector3.TransformNormal(new B.Vector3(side*2,0,0),m);this.emit(p,inherited.add(back.scale(-4-state.throttle*8)).add(sideways),'smoke',.15+state.throttle*.22,.7);}}else if(plane.moduleEmitters?.length){for(const at of plane.moduleEmitters){const p=trans(at),burn=state.boost?1.8:state.throttle;if(plane.type==='swift'&&!plane.fusionExhaust){this.emit(p,inherited.add(back.scale(6)).add(new B.Vector3(0,.6,0)),'smoke',.15,1.3);continue;}this.emit(p,inherited.add(back.scale(12+burn*30)),'blue',.35+burn*.3,.16+burn*.18);this.emit(p.add(back.scale(.4)),inherited.add(back.scale(17+burn*25)),'hot',.15+burn*.16,.09+burn*.12);}}else if(plane.type==='prop'){for(const s of[-1,1]){const p=trans([s*.74,-.42,2.55]);this.emit(p,inherited.add(back.scale(2.5+state.throttle*4)).add(new B.Vector3((Math.random()-.5)*.8,.6,0)),'smoke',.11+Math.random()*.08,1.3);}}
 else{for(const s of[-1,1]){const p=trans([s*1.23,-.15,-5.4]),burn=state.boost?1.85:state.throttle;this.emit(p,inherited.add(back.scale(5+burn*18)),state.boost?'blue':'hot',.2+burn*.2,.10+burn*.16);if(state.throttle>.3){this.emit(p.add(back.scale(.3)),inherited.add(back.scale(8+burn*14)),'fire',.28+burn*.28,.12+burn*.21);}if(Math.random()<.28)this.emit(p,inherited.add(back.scale(7)),'smoke',.2,.9);}}
 if(state.ground&&state.speed>7){const p=trans([(Math.random()-.5)*2,-1.6,-1]);this.emit(p,new B.Vector3((Math.random()-.5)*2,.5,-1),'dust',.2+Math.random()*.2,.8);}}
 }
 burst(position){for(let i=0;i<80;i++){this.emit(position.add(new B.Vector3((Math.random()-.5)*4,Math.random()*2,(Math.random()-.5)*4)),new B.Vector3((Math.random()-.5)*15,Math.random()*13,(Math.random()-.5)*15),i<30?'fire':'smoke',.3+Math.random()*.9,1+Math.random()*2);}}
 update(dt){if(this.flashLife>0){this.flashLife=Math.max(0,this.flashLife-dt);this.flash.intensity*=Math.exp(-dt*12);if(!this.flashLife)this.flash.intensity=0;}for(const a of this.items){if(a.life<=0)continue;a.life-=dt;if(a.life<=0){a.mesh.setEnabled(false);continue;}a.mesh.position.addInPlace(a.velocity.scale(dt));a.velocity.y+=dt*(a.type==='spark'?-9.81:a.type==='smoke'?.7:a.type==='dust'?.1:0);if(a.type==='spark'){a.velocity.scaleInPlace(Math.exp(-dt*.6));const h=Math.max(0,groundHeight(a.mesh.position.x,a.mesh.position.z))+.05;if(a.mesh.position.y<h){a.mesh.position.y=h;a.velocity.y=Math.abs(a.velocity.y)*.25;a.velocity.x*=.7;a.velocity.z*=.7;}}const t=1-a.life/a.max,scale=a.size*(a.type==='smoke'?1+t*3:a.type==='dust'?1+t*2:1-t*.75);a.mesh.scaling.setAll(scale*(a.life<.15?a.life/.15:1));a.mesh.rotation.z+=dt*.5;}}
 clear(){for(const a of this.items){a.life=0;a.mesh.setEnabled(false);}for(const ps of this.clouds){ps.reset();ps.manualEmitCount=0;ps.start();}this.flashLife=0;this.flash.intensity=0;this.timer=0;}
}
export class EngineAudio{
 constructor(){this.enabled=false;this.ctx=null;}
 async toggle(){if(!this.ctx){const C=window.AudioContext||window.webkitAudioContext;if(!C)return false;this.ctx=new C();this.master=this.ctx.createGain();this.master.gain.value=0;this.master.connect(this.ctx.destination);this.osc=this.ctx.createOscillator();this.osc.type='sawtooth';this.osc.frequency.value=50;this.filter=this.ctx.createBiquadFilter();this.filter.type='lowpass';this.filter.frequency.value=240;this.osc.connect(this.filter);this.filter.connect(this.master);this.osc.start();const buf=this.ctx.createBuffer(1,this.ctx.sampleRate*2,this.ctx.sampleRate);const data=buf.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;this.noise=this.ctx.createBufferSource();this.noise.buffer=buf;this.noise.loop=true;this.noiseGain=this.ctx.createGain();this.noiseGain.gain.value=.2;this.noise.connect(this.noiseGain);this.noiseGain.connect(this.filter);this.noise.start();}await this.ctx.resume();this.enabled=!this.enabled;return this.enabled;}
 missileLaunch(){if(!this.enabled||!this.ctx)return;const ctx=this.ctx,buffer=ctx.createBuffer(1,Math.floor(ctx.sampleRate*.4),ctx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*Math.sin(Math.PI*i/data.length)*.35;const source=ctx.createBufferSource(),filter=ctx.createBiquadFilter();source.buffer=buffer;filter.type='lowpass';filter.frequency.value=1900;source.connect(filter);filter.connect(ctx.destination);source.start();source.onended=()=>{source.disconnect();filter.disconnect();};}
 sonicBoom(){if(!this.enabled||!this.ctx)return;const ctx=this.ctx,buffer=ctx.createBuffer(1,Math.floor(ctx.sampleRate*.95),ctx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++){const t=i/ctx.sampleRate,a=Math.max(0,1-t/.22),b=Math.max(0,1-Math.abs(t-.22)/.16);data[i]=.55*Math.sin(t*2*Math.PI*48)*Math.exp(-t*9)+(Math.random()*2-1)*(a*.45+b*.22);}const source=ctx.createBufferSource(),filter=ctx.createBiquadFilter(),gain=ctx.createGain();source.buffer=buffer;filter.type='lowpass';filter.frequency.value=480;gain.gain.value=.38;source.connect(filter);filter.connect(gain);gain.connect(ctx.destination);source.start();source.onended=()=>{source.disconnect();filter.disconnect();gain.disconnect();};}
 impact(crashed=true){if(!crashed||!this.enabled||!this.ctx)return;const ctx=this.ctx,buffer=ctx.createBuffer(1,Math.floor(ctx.sampleRate*1.4),ctx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*Math.exp(-i/data.length*4);const source=ctx.createBufferSource();source.buffer=buffer;const filter=ctx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=650;const gain=ctx.createGain();gain.gain.value=.22;source.connect(filter);filter.connect(gain);gain.connect(ctx.destination);source.start();source.onended=()=>{source.disconnect();filter.disconnect();gain.disconnect();};}
 update(state,type,muted){if(!this.ctx)return;const now=this.ctx.currentTime;this.master.gain.setTargetAtTime(this.enabled&&!muted?.018+state.throttle*.034:0,now,.1);this.osc.frequency.setTargetAtTime((type==='prop'||type==='swift')?37+state.throttle*65:65+state.throttle*170,now,.15);this.filter.frequency.setTargetAtTime((type==='prop'||type==='swift')?180+state.throttle*360:500+state.throttle*1200,now,.15);this.noiseGain.gain.setTargetAtTime((type==='prop'||type==='swift')?.08:.55,now,.2);}
}
